{
 "modules": [
  {
   "id": "set_size_dependent_wm_lapse",
   "name": "Set-Size-Dependent WM Lapse",
   "description": "Working memory reliability decreases at higher set sizes, modeled as a lapse rate that scales linearly from 0 at set size 3 to a maximum at set size 6, blending the WM policy with a uniform distribution. Also includes arbitration between RL and WM based on the magnitude of the RL prediction error.",
   "params": [
    {
     "name": "set_size_dependent_wm_lapse_lapse0",
     "bounds": [
      0,
      1
     ]
    }
   ],
   "slots": {
    "probs_extra": "set_size_dependent_wm_lapse_val = 0.0 if nS <= 3 else np.clip(set_size_dependent_wm_lapse_lapse0 * (float(nS - 3) / 3.0), 0.0, 1.0)\nprobs_wm = (1.0 - set_size_dependent_wm_lapse_val) * probs_wm + set_size_dependent_wm_lapse_val * (1.0 / nA)\nprobs = mix * probs_wm + (1.0 - mix) * probs_rl"
   },
   "overrides": {
    "mix_weight": "np.clip(wm_weight * (1.0 - abs(r - q[s, a])), 0.0, 1.0)"
   },
   "provenance": [
    13
   ],
   "excludes": [
    "load_driven_wm_noise",
    "wm_set_size_retrieval_noise",
    "set_size_wm_noise"
   ]
  },
  {
   "id": "asymmetric_fixed_wm_update",
   "name": "Asymmetric Fixed-Rate WM Updating",
   "description": "Working memory updates perfectly after positive feedback but only partially decays the chosen action's weight and renormalizes after negative feedback, using fixed learning rates.",
   "params": [],
   "slots": {},
   "overrides": {
    "wm_update": "if r > 0.0:\n    w[s, :] = 0.0\n    w[s, a] = 1.0\nelse:\n    w[s, a] = max(1e-12, 0.8 * w[s, a])\n    asymmetric_fixed_wm_update_sum = np.sum(w[s, :])\n    if asymmetric_fixed_wm_update_sum > 0:\n        w[s, :] /= asymmetric_fixed_wm_update_sum"
   },
   "provenance": [
    13
   ],
   "excludes": [
    "wm_asymmetric_update_p1",
    "wm_asymmetric_update_p2",
    "unified_wm_update_decay",
    "wm_perfect_encoding_on_reward",
    "asymmetric_wm_update",
    "load_dependent_wm_learning",
    "arbitration_scaled_wm_update"
   ]
  }
 ]
}
